       if (qLen > 0) $q.attr("maxlength", qLen); // AD_Column.FieldLength cap\n        bindAmountInput($q);\n        $q.on("blur", function () {\n          commitField(line, "quantity", parseNum($q.val()));\n          editing = null;\n          render();\n        });\n        $q.on("keydown", function (e) {\n          e.stopPropagation();\n          if (e.key === "Tab") {\n            e.preventDefault();\n            advanceField(line, "quantity", parseNum($q.val()), e.shiftKey ? -1 : 1);\n            return;\n          }\n          if (e.key === "Enter") $q.blur();\n          if (e.key === "Escape") {\n            editing = null;\n            render();\n          }\n        });\n        wrap.append($q);\n        setTimeout(function () {\n          $q.focus();\n        }, 0);\n      } else {\n        var hasQ = v.QtyEntered !== undefined && v.QtyEntered !== "" && +v.QtyEntered !== 0;\n        wrap.append(dispInput(line, "quantity", hasQ ? fmtAmtInput(v.QtyEntered, 2) : "", {\n          align: "right",\n          placeholder: lbl("VAS_074_Qty", "Qty"),\n          cls: "vas-cil-qtyval"\n        }));\n      }\n\n      // UOM (bottom) — real editable C_UOM dropdown, options filtered to this\n      // line\'s context (C_UOM_ID AD_Val_Rule). Render with what is cached now,\n      // then refine in place once the per-row list arrives.\n      if (editUom) {\n        var $sel = $(\'<select class="vas-cil-cell-edit__select"></select>\');\n        fillUomOptions($sel, line);\n        ensureRowLookups(line, function () {\n          if (editing && editing.rowId === line.rowId && editing.field === "uom" && $sel.closest("body").length) fillUomOptions($sel, line);\n        });\n        $sel.on("change", function () {\n          setUom(line, parseInt($sel.val(), 10), $sel.find("option:selected").text());\n        });\n        $sel.on("blur", function () {\n          editing = null;\n          render();\n        });\n        $sel.on("keydown", function (e) {\n          e.stopPropagation();\n          if (e.key === "Tab") {\n            e.preventDefault();\n            advanceField(line, "uom", parseInt($sel.val(), 10), e.shiftKey ? -1 : 1);\n            return;\n          }\n          if (e.key === "Enter") $sel.blur();\n          if (e.key === "Escape") {\n            editing = null;\n            render();\n          }\n        });\n        wrap.append($sel);\n        setTimeout(function () {\n          $sel.focus();\n        }, 0);\n      } else {\n        wrap.append(dispInput(line, "uom", line.display.uomName || "", {\n          align: "right",\n          placeholder: lbl("VAS_074_Uom", "UOM"),\n          cls: "vas-cil-uomsub vas-cil-cell-disp--sub",\n          readOnly: uomRO\n        }));\n      }\n      return cell;\n    }\n    function renderTaxCell(line) {\n      var v = line.values;\n      var editable = parent && parent.IsEditable;\n      var cell = $(\'<div class="vas-cil-cell" role="cell"></div>\');\n      var wrap = $(\'<div class="vas-cil-cell-edit"></div>\');\n      var isEditing = editing && editing.rowId === line.rowId && editing.field === "tax";\n      if (isEditing) wrap.addClass("is-editing");\n      cell.append(wrap);\n      if (isEditing) {\n        // Tax options filtered to this line\'s context (C_Tax_ID AD_Val_Rule);\n        // refined in place once the per-row list arrives.\n        var $sel = $(\'<select class="vas-cil-cell-edit__select"></select>\');\n        fillTaxOptions($sel, line);\n        ensureRowLookups(line, function () {\n          if (editing && editing.rowId === line.rowId && editing.field === "tax" && $sel.closest("body").length) fillTaxOptions($sel, line);\n        });\n        $sel.on("change", function () {\n          setTax(line, parseInt($sel.val(), 10), $sel.find("option:selected").text());\n        });\n        $sel.on("blur", function () {\n          editing = null;\n          render();\n        });\n        $sel.on("keydown", function (e) {\n          e.stopPropagation();\n          if (e.key